```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Flappy Bird — HTML5</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;700;800;900&family=Press+Start+2P&display=swap" rel="stylesheet">
<style>
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0; font-family:"Nunito",system-ui,sans-serif; color:#bfe4ee;
    background:
      radial-gradient(900px 480px at 78% -8%, rgba(46,116,138,.55), transparent 62%),
      radial-gradient(760px 420px at 8% 108%, rgba(34,92,114,.5), transparent 60%),
      linear-gradient(160deg,#0d2b38,#081a24 55%,#0a1e28);
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    min-height:100svh; padding:18px 14px 26px; overflow-x:hidden;
  }
  /* ambient page layers */
  .bg{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
  .dotgrid{position:absolute;inset:0;
    background-image:radial-gradient(rgba(143,208,224,.07) 1px, transparent 1.6px);
    background-size:26px 26px;
    -webkit-mask-image:radial-gradient(ellipse at 50% 42%, #000 25%, transparent 78%);
            mask-image:radial-gradient(ellipse at 50% 42%, #000 25%, transparent 78%);}
  .drift{position:absolute;left:0;border-radius:50%;background:rgba(214,244,250,.05);filter:blur(26px);animation:drift 95s linear infinite}
  .d1{width:340px;height:130px;top:10%}
  .d2{width:260px;height:100px;top:52%;background:rgba(214,244,250,.06);animation-duration:70s;animation-delay:-30s}
  .d3{width:430px;height:150px;top:80%;animation-duration:120s;animation-delay:-70s}
  @keyframes drift{from{transform:translateX(-45%)}to{transform:translateX(105vw)}}
  .glow{position:absolute;left:50%;top:45%;width:660px;height:540px;transform:translate(-50%,-50%);
    background:radial-gradient(closest-side, rgba(255,216,77,.13), rgba(255,216,77,.03) 55%, transparent 75%);
    animation:breathe 7s ease-in-out infinite}
  @keyframes breathe{0%,100%{opacity:.7;transform:translate(-50%,-50%) scale(1)}50%{opacity:1;transform:translate(-50%,-50%) scale(1.06)}}

  /* cabinet */
  .cabinet{position:relative;z-index:1;width:max-content;max-width:100%;
    background:linear-gradient(#143543,#0f2a35);
    border:1px solid #1d4a58;border-radius:20px;padding:12px;
    box-shadow:0 34px 70px -24px rgba(0,0,0,.75), 0 0 0 5px rgba(4,15,20,.4), inset 0 1px 0 rgba(255,255,255,.05);
    transition:transform .35s ease}
  .cabinet:hover{transform:translateY(-3px)}
  .cab-top{display:flex;align-items:center;justify-content:space-between;padding:2px 4px 10px}
  .brand{font-family:"Press Start 2P",monospace;font-size:11px;letter-spacing:1px;color:#ffd84d;
    display:flex;align-items:center;gap:9px;text-shadow:0 2px 0 rgba(0,0,0,.45)}
  .brand svg{display:block;filter:drop-shadow(0 2px 0 rgba(0,0,0,.35))}
  .cab-right{display:flex;align-items:center;gap:8px}
  .led{width:8px;height:8px;border-radius:50%;display:inline-block;animation:led 2.4s ease-in-out infinite}
  .l1{background:#ff6259;box-shadow:0 0 8px #ff6259}
  .l2{background:#ffd84d;box-shadow:0 0 8px #ffd84d;animation-delay:.4s}
  .l3{background:#5fe08b;box-shadow:0 0 8px #5fe08b;animation-delay:.8s}
  @keyframes led{0%,100%{opacity:1}50%{opacity:.35}}
  .mute{width:32px;height:32px;border-radius:9px;border:1px solid #2a5a6a;background:#0c222c;color:#9fd8e8;
    font-size:15px;line-height:1;cursor:pointer;transition:all .15s;box-shadow:inset 0 -2px 0 rgba(0,0,0,.35)}
  .mute:hover{background:#123645;border-color:#3d7c92;transform:translateY(-1px)}
  .mute:active{transform:translateY(1px) scale(.94)}
  .mute[aria-pressed="true"]{color:#55707c;text-decoration:line-through;box-shadow:none}
  .screen{position:relative;border-radius:12px;overflow:hidden;background:#79c8d6;
    box-shadow:inset 0 0 0 3px #081a22, 0 6px 18px rgba(0,0,0,.4)}
  #game{display:block;width:420px;height:auto;touch-action:manipulation;cursor:pointer;
    -webkit-user-select:none;user-select:none}
  .scan{position:absolute;inset:0;pointer-events:none;
    background:radial-gradient(130% 105% at 50% 0%, transparent 55%, rgba(4,20,26,.22))}
  .cab-bottom{display:flex;justify-content:center;flex-wrap:wrap;gap:6px 18px;padding:10px 4px 2px;
    font-size:12px;font-weight:800;color:#6fa9ba;letter-spacing:.3px}
  .key kbd{font-family:"Nunito";font-weight:900;font-size:10px;letter-spacing:.5px;color:#d9f2f8;
    background:#0c222c;border:1px solid #2a5a6a;border-bottom-width:3px;border-radius:6px;
    padding:2px 7px;margin:0 2px;box-shadow:0 2px 0 rgba(0,0,0,.4)}
  .credit{margin:14px 0 0;font-size:12px;font-weight:700;color:rgba(143,208,224,.45);letter-spacing:.4px;text-align:center}
  @media (prefers-reduced-motion: reduce){
    .drift,.glow,.led{animation:none}.cabinet{transition:none}
  }
</style>
</head>
<body>

  <div class="bg" aria-hidden="true">
    <i class="dotgrid"></i><i class="drift d1"></i><i class="drift d2"></i><i class="drift d3"></i><i class="glow"></i>
  </div>

  <main class="cabinet" aria-label="Flappy Bird">
    <div class="cab-top">
      <span class="brand">
        <svg viewBox="0 0 12 10" width="22" height="19" shape-rendering="crispEdges" aria-hidden="true">
          <rect x="1" y="2" width="8" height="6" fill="#ffd84d"/>
          <rect x="2" y="1" width="5" height="2" fill="#ffd84d"/>
          <rect x="7" y="3" width="1" height="2" fill="#26211a"/>
          <rect x="2" y="5" width="3" height="2" fill="#f5a51b"/>
          <rect x="9" y="4" width="3" height="2" fill="#ff7f3f"/>
        </svg>
        FLAPPY&nbsp;BIRD
      </span>
      <span class="cab-right">
        <i class="led l1"></i><i class="led l2"></i><i class="led l3"></i>
        <button id="mute" class="mute" aria-pressed="false" title="Sound on (M)">♪</button>
      </span>
    </div>
    <div class="screen">
      <canvas id="game" width="420" height="640" aria-label="Flappy Bird playfield"></canvas>
      <div class="scan" aria-hidden="true"></div>
    </div>
    <div class="cab-bottom">
      <span class="key"><kbd>Space</kbd>/<kbd>Click</kbd> flap</span>
      <span class="key"><kbd>P</kbd> pause</span>
      <span class="key"><kbd>M</kbd> sound</span>
    </div>
  </main>

  <p class="credit">one canvas · zero sprites · gravity, particles &amp; WebAudio chiptunes</p>

<script>
(() => {
'use strict';
/* ================= setup ================= */
const W = 420, H = 640, GROUND = 536;
const DPR = Math.min(2, window.devicePixelRatio || 1);
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = W * DPR; canvas.height = H * DPR;
ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

const PX = '"Press Start 2P", monospace';
const UI = '"Nunito", sans-serif';

/* physics / level constants */
const GRAV = 1550, FLAP = -440, VMAX = 700;
const BIRD_X = 132, BIRD_R = 15;
const PIPE_W = 72, GAP = 158, SPEED = 176, SPACING = 262;
const GAP_MIN = 60 + GAP / 2, GAP_MAX = GROUND - GAP / 2 - 52;

/* state */
const ST = {READY:0, PLAY:1, DYING:2, OVER:3, PAUSE:4};
let state = ST.READY;
let simT = 0, worldDist = 0, spawnAcc = 0;
let pipes = [], parts = [];
let score = 0, best = 0, newBest = false;
let flash = 0, shake = 0, popT = 1, panelT = 0, overAt = 0;
let wingPhase = 0, wingBoost = 0;
let muted = false;
try { best = +localStorage.getItem('flappy.best') || 0; } catch(e){}
try { muted = localStorage.getItem('flappy.mute') === '1'; } catch(e){}

const bird = { x: BIRD_X, y: 300, vy: 0, rot: 0 };
const clouds = [
  {x:70,y:96,s:1,v:9},{x:260,y:170,s:.72,v:7},{x:380,y:64,s:.85,v:10},
  {x:170,y:268,s:.5,v:6},{x:330,y:330,s:.6,v:6.5}
];

/* ================= audio (synth chiptune, no assets) ================= */
const Sfx = (() => {
  let c = null;
  const ok = () => {
    if (!c) { try { c = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){} }
    if (c && c.state === 'suspended') c.resume();
    return c;
  };
  function tone(f0, f1, t, type, v, when = 0) {
    const a = ok(); if (!a || muted) return;
    const o = a.createOscillator(), g = a.createGain(), n = a.currentTime + when;
    o.type = type;
    o.frequency.setValueAtTime(Math.max(30, f0), n);
    if (f1) o.frequency.exponentialRampToValueAtTime(Math.max(30, f1), n + t);
    g.gain.setValueAtTime(0.0001, n);
    g.gain.exponentialRampToValueAtTime(v, n + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, n + t);
    o.connect(g).connect(a.destination); o.start(n); o.stop(n + t + 0.06);
  }
  function noise(t, v, when = 0, f = 900) {
    const a = ok(); if (!a || muted) return;
    const n = Math.floor(a.sampleRate * t), buf = a.createBuffer(1, n, a.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
    const s = a.createBufferSource(); s.buffer = buf;
    const fl = a.createBiquadFilter(); fl.type = 'lowpass'; fl.frequency.value = f;
    const g = a.createGain(), q = a.currentTime + when;
    g.gain.setValueAtTime(v, q); g.gain.exponentialRampToValueAtTime(0.0001, q + t);
    s.connect(fl).connect(g).connect(a.destination); s.start(q);
  }
  return {
    unlock: ok,
    flap(){ tone(430, 860, .09, 'triangle', .2); },
    point(){ tone(987, 987, .06, 'square', .09); tone(1318, 1318, .09, 'square', .09, .065); },
    hit(){ tone(200, 55, .25, 'sawtooth', .28); noise(.18, .3, 0, 1400); },
    die(){ tone(560, 160, .4, 'triangle', .16, .12); },
    land(){ tone(150, 60, .12, 'sine', .25); }
  };
})();

/* ================= helpers ================= */
const rnd = (a, b) => a + Math.random() * (b - a);
function circle(x, y, r) { ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill(); }
