Here's a complete, self-contained canvas-based Slack clone. Save it as `index.html` and open it in any modern browser — everything (layout, rendering, hit-testing, animations, the bot engine) is drawn and driven through a single HTML5 Canvas, with a hidden native input underneath for real text-entry accessibility.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>Ember Studio — a living team chat</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Sora:wght@600;700;800&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap" rel="stylesheet">
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#160E1C;-webkit-font-smoothing:antialiased}
  body{font-family:'IBM Plex Sans',system-ui,sans-serif}
  #app{display:block;position:fixed;inset:0;touch-action:none;user-select:none;-webkit-user-select:none;cursor:default}
  .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
  /* hidden native input: real keyboard/IME/screen-reader capture, mirrored onto the canvas composer */
  #ci{position:fixed;left:2px;top:2px;width:3px;height:3px;opacity:.01;border:0;padding:0;background:transparent;
      font-family:'IBM Plex Sans',system-ui,sans-serif;font-size:14px;color:transparent;caret-color:transparent;outline:none}
  #ci:focus{outline:none}
</style>
</head>
<body>
<canvas id="app" role="application" tabindex="1"
  aria-label="Ember Studio, a team chat. Tab moves between the channel list, people list and message composer. Type a colon for emoji. Arrow up when the composer is empty edits your last message. Press question mark for shortcuts."></canvas>
<input id="ci" aria-label="Message composer" autocomplete="off" autocapitalize="sentences" spellcheck="false">
<div id="live" class="sr-only" role="status" aria-live="polite"></div>

<script>
'use strict';
/* ================================================================
   EMBER STUDIO — a canvas-rendered Slack-like chat
   Everything is drawn on one <canvas>. A visually-hidden native
   input captures real keyboard input so typing stays accessible.
   ================================================================ */

const cv = document.getElementById('app');
const ctx = cv.getContext('2d');
const ci = document.getElementById('ci');
const liveEl = document.getElementById('live');
const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
const FINE = matchMedia('(pointer: fine)').matches;

/* ---------------- helpers ---------------- */
const $id = s => document.getElementById(s);
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const lerp=(a,b,t)=>a+(b-a)*t;
const easeIO=t=>t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;
const easeO=t=>1-Math.pow(1-t,3);
const R=(a,b)=>a+Math.random()*(b-a);
const RI=(a,b)=>Math.floor(R(a,b+1));
const pick=a=>a[Math.floor(Math.random()*a.length)];
const now=()=>performance.now();
let UID=1; const uid=()=>UID++;
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0)/4294967295}
function hsl(h,s,l){return `hsl(${h} ${s}% ${l}%)`}
function fmtTime(ts){const d=new Date(ts);let h=d.getHours(),m=d.getMinutes();const ap=h>=12?'PM':'AM';h=h%12||12;return h+':'+String(m).padStart(2,'0')+' '+ap}
function dayKey(ts){const d=new Date(ts);return d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate()}
function dayLabel(ts){const d=new Date(ts);const t=new Date();const y=new Date(t);y.setDate(t.getDate()-1);
  if(dayKey(ts)===dayKey(t.getTime()))return 'Today'; if(dayKey(ts)===dayKey(y.getTime()))return 'Yesterday';
  return d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}
function fmtAgo(ms){const s=Math.floor(ms/1000);if(s<60)return 'just now';const m=Math.floor(s/60);if(m<60)return m+'m';
  const h=Math.floor(m/60);if(h<24)return h+'h';return Math.floor(h/24)+'d'}
function announce(msg){liveEl.textContent='';requestAnimationFrame(()=>{liveEl.textContent=msg})}
function rr(x,y,w,h,r){r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
function fRR(x,y,w,h,r,fill){rr(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill()}
function strokeRR(x,y,w,h,r,stroke,lw){rr(x,y,w,h,r);ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}
function txt(s,x,y,font,fill,align='left',base='alphabetic'){ctx.font=font;ctx.fillStyle=fill;ctx.textAlign=align;ctx.textBaseline=base;ctx.fillText(s,x,y)}
const PB=(w,s)=>`${w} ${s}px "IBM Plex Sans",system-ui,sans-serif`;
const PBD=(w,s)=>`${w} ${s}px "Sora","IBM Plex Sans",sans-serif`;
function trunc(s,maxW,font){ctx.font=font;let t=s;if(ctx.measureText(t).width<=maxW)return t;
  while(t.length>1&&ctx.measureText(t+'…').width>maxW)t=t.slice(0,-1);return t+'…'}
function wrapText(str,font,maxW){ctx.font=font;const out=[];
  for(const para of String(str).split('\n')){
    if(maxW<=0){out.push(para);continue}
    let line='';
    for(let word of para.split(' ')){
      let test=line?line+' '+word:word;
      if(ctx.measureText(test).width<=maxW||!line){line=test;continue}
      // hard-break huge tokens (links etc.)
      if(ctx.measureText(word).width>maxW){
        if(line){out.push(line);line=''}
        let chunk='';
        for(const c of word){ if(ctx.measureText(chunk+c).width>maxW&&chunk){out.push(chunk);chunk=c} else chunk+=c }
        line=chunk; continue;
      }
      out.push(line);line=word;
    }
    out.push(line);
  }
  return out.length?out:[''];
}

