function parseEm(s){return String(s).replace(/:([a-z0-9_+]{2,26}):/gi,(m,n)=>EMOJI_AL[n.toLowerCase()]??m)}
function searchEmoji(q){const t=(q||'').toLowerCase().replace(/ /g,'');
  const out=[];
  for(const [c,...ns] of EMOJI){if(out.length>=48)break;for(const n of [ns[0],...ns])if(n.startsWith(t)){out.push(c);break}}
