  const w=Math.min(324,W-24),h=H-L.top-24;return{x:W-w-12,y:L.top+12,w,h,slide:L.panelX};
}
function helpRect(){const w=Math.min(360,W-32),h=308;return{x:(W-w)/2,y:(H-h)/2-20,w,h}}
function drawerRect(){return{x:0,y:0,w:Math.min(300,W*.85),h:H}}
function inputPickerRect(){
  const w=Math.min(460,L.chat.w-24);
  const list=searchEmoji(state.picker?state.picker.query:'');
  const cols=L.mobile?6:8, rows=Math.ceil(list.length/cols)||1;
  const h=52+rows*46+16;
  return{x:clamp(L.comp.x+40,12,W-w-12),y:L.comp.y-h-10,w,h,cols}
}
function reactPickerRect(){
  const w=Math.min(300,L.chat.w-24),h=236;
  return{x:clamp((L.chat.x+L.chat.w/2)-w/2,12,W-w-12),y:L.comp.y-h-14,w,h}
}

/* ---------------- render ---------------- */
let lastT=0,lastSec=-1,drag=null;
function frame(t){
  const dt=Math.min(0.05,(t-lastT)/1000||0);lastT=t;
