  const padX=14;
  const innerW=Math.max(120,w-24-56-56-40);
  const lines=wrapText(v||' ',PB(400,14),innerW);
  const n=clamp(lines.length,1,5);
  const h=22+n*M_LINEH;
  const x=L.chat.x+12, ww=Math.min(w-24,980);
  const y=H-h-12;
  L.comp={x,y,w:ww,h,innerW,lines,innerX:x+56+40,padX};
  L.compTop=y;
  L.viewH=y-8-(L.top+L.headH);
  for(const ch of CH){ch.max=Math.max(0,ch.totalH-L.viewH);
    ch.scroll.off=clamp(ch.scroll.off,0,ch.max);ch.scroll.tgt=clamp(ch.scroll.tgt,0,ch.max)}
}

/* ---------------- message layout ---------------- */
function relayoutChannel(ch){
  const padL=L.mobile?12:36, padR=L.mobile?12:24;
  const textX=padL+44, textW=L.chat.w-textX-16-padR;
  let y=0;const items=[];let lastDay=null,lastUid=null,lastTs=0;
  // intro block
  {
    const introH=L.mobile?96:112;
    items.push({kind:'intro',y,h:introH});y+=introH;
  }
  for(const m of ch.messages){
    const dk=dayKey(m.ts);
    if(dk!==lastDay){items.push({kind:'day',y,h:34,ts:m.ts});y+=34;lastDay=dk;lastUid=null}
    const compact=(m.userId===lastUid&&(m.ts-lastTs)<5*6e4);
    const parsed=parseEm(m.text);
    const lines=wrapText(parsed,M_FONT(),textW);
    const rh=m.reactions.size?30:0;
    const topPad=compact?4:16;
    const h=topPad+lines.length*M_LINEH+rh+(compact?4:12);
    items.push({kind:'msg',m,y,h,lines,compact,textX,textW});
    y+=h;lastUid=m.userId;lastTs=m.ts;
  }
  ch.items=items;ch.totalH=y;
  ch.max=Math.max(0,ch.totalH-L.viewH);
  const s=ch.scroll;s.off=clamp(s.off,0,ch.max);s.tgt=clamp(s.tgt,0,ch.max);
}
function relayoutAll(){for(const ch of CH)relayoutChannel(ch)}
function openChannel(id,push){
  if(state.cur===id){L&&closeOverlays();return}
  state.cur=id;state.editing=null;state.picker=null;
  const ch=CH.find(c=>c.id===id);
  if(push)ci.value='';
  if(ch.unread){announce(`Opened #${ch.name}, ${ch.unread} unread. Now reading.`);ch.unread=0}else announce('Opened #'+ch.name);
  state.drawer=false;
  relayoutChannel(ch);
  ch.scroll.tgt=ch.max;ch.scroll.off=ch.max;ch.scroll.vel=0;ch.hasNew=false;
  ci.setAttribute('aria-label','Message #'+ch.name);
}

/* ---------------- avatars ---------------- */
function avatar(u,x,y,s,ringBg,pulse){
  const r=s>22?Math.round(s*.22):6;
  const g=ctx.createLinearGradient(x,y,x,y+s);
  g.addColorStop(0,hsl(u.h,58,60));g.addColorStop(1,hsl(u.h,64,42));
  fRR(x,y,s,s,r,g);
  ctx.save();rr(x,y,s,s,r);ctx.clip();
  const init=u.name.split(' ').map(p=>p[0]).slice(0,2).join('');
  txt(init,x+s/2,y+s/2,PBD(700,Math.round(s*.42)),'rgba(255,255,255,.95)','center','middle');
  ctx.restore();
  if(ringBg!=null&&s>=20){
    const r2=Math.max(4,s*.16);
    if(pulse){const a=(Math.sin(now()/620+x*0.13)+1)/2;
      ctx.beginPath();ctx.arc(x+s-r2*.4,y+s-r2*.4,r2+2.5*a,0,7);ctx.fillStyle=`rgba(46,184,114,${.28*(1-a)})`;ctx.fill()}
    ctx.beginPath();ctx.arc(x+s-r2*.4,y+s-r2*.4,r2,0,7);ctx.fillStyle=ringBg;ctx.fill();
    ctx.beginPath();ctx.arc(x+s-r2*.4,y+s-r2*.4,r2*.62,0,7);
    ctx.fillStyle=u.pres==='away'?C.away:u.pres==='dnd'?C.dnd:C.ok;ctx.fill();
  }
}

/* ---------------- bot engine ---------------- */
let pending=[]; // {t,fn}
function later(ms,fn){pending.push({t:now()+ms,fn})}
function pickChannelFor(bot){
  const r=Math.random();
  if(r<0.30&&state.auto===true){} // bias below
  if(Math.random()<0.34)return CH.find(c=>c.id===state.cur);
  let rr=Math.random(),acc=0;
  for(const ch of CH){acc+=ch.w;if(rr<=acc)return ch}
  return pick(CH);
}
function channelForRole(role){
  if(role==='Design')return pick(['design','random','general']);
  if(role==='Backend'||role==='Frontend')return pick(['engineering','general','random']);
  if(role==='PM')return pick(['general','announcements','design']);
  if(role==='Data')return pick(['engineering','general','random']);
  return pick(['general','random']);
}
function botStart(b,t){
  // sometimes just react to a recent message
  let ch=pickChannelFor(b);
  if(Math.random()<0.18&&ch.messages.length>2&&Math.random()<0.7){
    const m=pick(ch.messages.slice(-8));
    if(m.userId!==b.id){toggleReact(ch,m,b.id,pick(REACT_SET));}
    b.nextAt=t+idleTime(b);return;
  }
  // otherwise type a real message
  ch=pickChannelFor(b);
  let text=pick(ch.pool);
  if(ch.lastUsed>=0&&text===ch.pool[ch.lastUsed])text=pick(ch.pool);
  ch.lastUsed=ch.pool.indexOf(text);
  const words=text.split(' ').length;
  const dur=clamp(words/(b.u.wpm/60)*1000*PACE[state.pace].mult*0.9,900,5200)*R(.85,1.2);
  const pre=R(200,900);
  const burst=text.length>90&&Math.random()<0.5;
  b.act={ch,text,t0:t,pre,dur,burst,done:false,
    reply:false};
}
function botTick(t){
  for(const b of state.bots){
    if(!b.active)continue;
    if(!b.act){if(t>=b.nextAt)botStart(b,t);continue}
    const a=b.act;const el=t-a.t0-a.pre;
    if(el<0){a.ch.typing.add(b.id);continue}
    const frac=el/a.dur;
    const on=!a.burst||frac<0.55||frac>0.8;
    if(on)a.ch.typing.add(b.id);else a.ch.typing.delete(b.id);
    if(el>=a.dur&&!a.done){
      a.done=true;a.ch.typing.delete(b.id);
      postBotMessage(a.ch,b.u,a.text);
      b.nextAt=t+idleTime(b);b.act=null;
    }
  }
}
function idleTime(b){
  return Math.max(4000,(6000+Math.random()*20000)*PACE[state.pace].mult*(1+activeBots().length*0.16));
}
function postBotMessage(ch,user,text,replyTo){
  const m=msg(ch.id,user.id,0,text);m.ts=Date.now();
  ch.messages.push(m);m.birth=now();
  if(ch.messages.length>160)ch.messages.shift();
  relayoutChannel(ch);
  if(ch.id===state.cur){
    const s=ch.scroll;
    if(s.off>ch.max-240||RM){s.tgt=ch.max}
    else ch.hasNew=true;
  } else ch.unread++;
  if(replyTo){
    // bot reacting to user's message: handled separately; here just announce
  }
  announce(`${user.name} in ${ch.name.startsWith('dm:')?'direct message':'#'+ch.name}: ${text}`.slice(0,160));
  if(Math.random()<0.10){ // bot-to-bot flavor
    const others=ch.messages.slice(-10).filter(x=>x.userId!==user.id&&x.ts>m.ts-30*6e4);
    if(others.length&&state.auto)later(R(1500,5000),()=>toggleReact(ch,pick(others),user.id,pick(REACT_SET)));
  }
}
function userPosted(ch,my){
  if(!state.auto)return;
  const acts=activeBots();if(!acts.length)return;
  const r=Math.random();
  if(r<0.42){
    const b=pick(acts);
    later(R(1400,4500),()=>{if(b.active&&my.ch===ch.id)toggleReact(ch,my,b.id,pick(REACT_SET))});
  }
  if(r<0.78){
    const b=pick(acts);
    const pool=(REPLIES[ch.id]||REPLIES.general).concat(['Love it 👏','Great, thanks','On it!','Say more :eyes:']);
    later(R(2000,6500),()=>{
      if(!b.active)return;
      const t=now();const text=pick(pool);
      const dur=clamp(text.length/2.2,800,3200)*R(.9,1.25);
      b.act={ch,text,t0:t,pre:R(100,500),dur,burst:false,done:false,reply:true};
    });
  }
}
function toggleReact(ch,m,uidS,emoji){
  const old=m.reactions.get(emoji);
  let s=old?new Set(old):new Set();
  if(s.has(uidS))s.delete(uidS);else s.add(uidS);
  if(s.size)m.reactions.set(emoji,s);else m.reactions.delete(emoji);
  m.pulseT=now();
  relayoutChannel(ch);
}

/* ---------------- sending (with flight animation) ---------------- */
let flight=null;
function sendMessage(){
  const v=ci.value.trim();
  const ch=CH.find(c=>c.id===state.cur);
  if(state.picker){selectEmoji(state.picker.hi);return}
  if(state.editing){
    if(!v){state.editing=null;ci.value='';updateComposer();return}
    state.editing.text=v;state.editing.edited=true;state.editing.pulseT=now();
    relayoutChannel(ch);state.editing=null;ci.value='';updateComposer();
    announce('Message edited');return;
  }
  if(!v)return;
  const m=msg(ch.id,ME.id,0,v);m.ts=Date.now();
  ci.value='';updateComposer();
  const from={x:L.comp.x+L.comp.innerX,y:L.comp.y+L.comp.h/2};
  const to={x:L.chat.x+36,y:Math.min(H-90,L.compTop-40)};
  if(RM||L.mobile){
    m.birth=now();ch.messages.push(m);relayoutChannel(ch);
    ch.scroll.tgt=ch.max;userPosted(ch,m);announce('You sent: '+v.slice(0,80));
    flight=null;
  }else{
    flight={m,ch,from,to,t0:now(),dur:480};
  }
}
function finishFlight(){
  const f=flight;flight=null;
  const m=f.m;m.birth=now()-220; // small pop-in
  f.ch.messages.push(m);
  relayoutChannel(f.ch);
  f.ch.scroll.tgt=f.ch.max;f.ch.scroll.off=lerp(f.ch.scroll.off,f.ch.max,.5);
  userPosted(f.ch,m);
  announce('You sent: '+m.text.slice(0,80));
}

/* ---------------- input / picker ---------------- */
function refreshPickerQuery(){
  const v=ci.value;const mm=v.match(/:([a-z0-9]*)$/i);
  if(mm){
    if(!state.picker||state.picker.mode!=='input'){state.picker={mode:'input',query:mm[1],hi:0,openT:now()}}
    else state.picker.query=mm[1];
    state.picker.hi=clamp(state.picker.hi,0,Math.max(0,searchEmoji(state.picker.query).length-1));
  } else if(state.picker&&state.picker.mode==='input')state.picker=null;
}
function selectEmoji(i){
  const p=state.picker;if(!p)return;
  const list=searchEmoji(p.query);const e=list[i];if(!e)return;
  if(p.mode==='input'){
    ci.value=ci.value.replace(/:([a-z0-9]*)$/i,e+' ');
    state.picker=null;
  }else{
    toggleReact(CH.find(c=>c.id===state.cur),p.msg,ME.id,e);
    state.picker=null;
  }
  ci.focus({preventScroll:true});
  updateComposer();
}

/* ---------------- hotspots ---------------- */
let HOTS=[];
function hs(x,y,w,h,fn,tip,cursor='pointer'){HOTS.push({x,y,w,h,fn,tip,cursor})}
function hitTest(x,y){for(let i=HOTS.length-1;i>=0;i--){const h=HOTS[i];
  if(x>=h.x&&y>=h.y&&x<=h.x+h.w&&y<=h.y+h.h)return h}return null}

/* ---------------- focus ---------------- */
const FOCUS_ORDER=['channels','users','composer','panel','help'];
function focusTarget(f){
  switch(f.kind){
    case 'channels':{const r=L.channels[r.focusI]||L.channels[0];return r}
    case 'users':{const r=L.users[r.focusI]||L.users[0];return r}
    case 'composer':return L.comp?{x:L.comp.x,y:L.comp.y,w:L.comp.w,h:L.comp.h}:null;
    case 'panel':return state.panel?panelRect():null;
    case 'help':return state.help?helpRect():null;
  }
}
function moveFocus(dir){
  const avail=FOCUS_ORDER.filter(k=>k!=='panel'||state.panel).filter(k=>k!=='help'||state.help);
  let i=avail.indexOf(state.focus.kind);if(i<0)i=avail.indexOf('composer');
  i=(i+dir+avail.length*3)%avail.length;
  const k=avail[i];state.focus={kind:k};
  if((k==='channels'||k==='users')&&L.mobile)state.drawer=true;
  if(k==='composer')ci.focus({preventScroll:true});
}
function drawFocusRing(){
  const r=focusTarget(state.focus);if(!r)return;
  ctx.save();ctx.lineWidth=2.5;ctx.strokeStyle=C.accent2;
  ctx.shadowColor='rgba(0,0,0,.25)';ctx.shadowBlur=6;
  strokeRR(r.x-3,r.y-3,r.w+6,r.h+6,10,C.accent2,2.5);
  ctx.restore();
}

/* ---------------- panel / help / drawer rects ---------------- */
function panelRect(){
  if(L.mobile){const w=W-16,h=Math.min(470,H-96);return{x:8,y:H-h-8,w,h,slide:L.panelX}}
  const w=Math.min(324,W-24),h=H-L.top-24;return{x:W-w-12,y:L.top+12,w,h,slide:L.panelX};
}
function helpRect(){const w=Math.min(360,W-32),h=308;return{x:(W-w)/2,y:(H-h)/2-20,w,h}}
function drawerRect(){return{x:0,y:0,w:Math.min(300,W*.85),h:H}}
function inputPickerRect(){
  const w=Math.min(460,L.chat.w-24);
  const list=searchEmoji(state.picker?state.picker.query:'');
  const cols=L.mobile?6:8, rows=Math.ceil(list.length/cols)||1;
  const h=52+rows*46+16;
  return{x:clamp(L.comp.x+40,12,W-w-12),y:L.comp.y-h-10,w,h,cols}
}
function reactPickerRect(){
  const w=Math.min(300,L.chat.w-24),h=236;
