/* ---------------- render ---------------- */
let lastT=0,lastSec=-1,drag=null;
function frame(t){
  const dt=Math.min(0.05,(t-lastT)/1000||0);lastT=t;
  tick(t,dt);
  render(t);
  requestAnimationFrame(frame);
}
function tick(t,dt){
  botTick(t);
  // pending events
  pending=pending.filter(p=>{if(t>=p.t){p.fn();return false}return true});
  // flight
  if(flight){const f=flight;const k=clamp((t-f.t0)/f.dur,0,1);
    if(k>=1)finishFlight();}
  // scroll smoothing + inertia
  for(const ch of CH){if(ch.id!==state.cur&&ch.scroll.vel===0)continue;
    if(ch.id===state.cur&&!drag){ch.scroll.tgt+=ch.scroll.vel*dt;ch.scroll.vel*=Math.pow(0.86,dt*60);
      if(Math.abs(ch.scroll.vel)<30)ch.scroll.vel=0}
    ch.scroll.tgt=clamp(ch.scroll.tgt,0,ch.max);
    const s=ch.scroll;const k=1-Math.exp(-dt*12);
    s.off+=(s.tgt-s.off)*k;if(Math.abs(s.tgt-s.off)<.5)s.off=s.tgt;
  }
  // presence drift
  if(!state.lastPres&&t>state.lastPres){state.lastPres=t+R(30000,60000);
    const b=pick(state.bots);if(b.active){b.u.pres=b.u.pres==='away'?'online':'away'}}
  // panel / drawer slide
  L.panelX=L.panelX??1;L.panelX=lerp(L.panelX,state.panel?1:0,1-Math.exp(-dt*14));
  L.drawerX=L.drawerX??0;L.drawerX=lerp(L.drawerX,state.drawer?1:0,1-Math.exp(-dt*14));
  // toast
  if(state.toast&&t-state.toast.t0>state.toast.dur){state.toast=null}
  if(!state.tipI||t>state.nextTip){state.tipI=(state.tipI??0+1)%TIPS.length;state.nextTip=t+14000}
}

function render(t){
  ctx.clearRect(0,0,W,H);
  HOTS.length=0;
  drawChat(t);
  drawHeader(t);
  if(!L.mobile){drawRail(t);drawSidebar(t)}
  drawTopbar(t);
  drawFlight(t);
  if(state.drawer)drawDrawer(t);
  if(state.picker)drawPicker(t);
  if(state.panel)drawPanel(t);
  if(state.help)drawHelp();
  if(state.toast)drawToast(t);
  drawFocusRing();
  drawTooltip();
  // cursor
  const hv=state.hover;
  cv.style.cursor=hv?hv.cursor:'default';
}

/* ---- chat column ---- */
