    const ty=L.comp.y-26;
    const names=typers.slice(0,2).map(u=>u.name.split(' ')[0]).join(' and ')+(typers.length>2?' +'+(typers.length-2):'');
    const label=(typers.length>1?names+' are typing':names+' is typing');
    const dw=3*11;
    txt(label,cx+20+dw+8,ty+9,PB(500,12),C.mut);
    for(let i=0;i<3;i++){
      const b=RM?2:Math.abs(Math.sin(t/300+i*1.1))*4;
      ctx.beginPath();ctx.arc(cx+20+i*11+4,ty+6-b,3,0,7);ctx.fillStyle=C.accent;ctx.fill();
    }
  }
  drawComposer(t,ch);
  if(ch.hasNew){
    const w=130,h=32,x=cx+cw/2-w/2,y=L.comp.y-h-14;
    fRR(x,y,w,h,16,'rgba(36,26,46,.92)');
    txt('↓  New messages',cx+cw/2,y+h/2,PB(600,12),'#
